"/* ==========================================================================
   APEX UNIVERSITY COURSE REGISTRATION SYSTEM - STYLESHEET
   Features: Colorful modern palette, high accessibility (WCAG AA), responsive
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. CSS Custom Properties / Design Tokens
   -------------------------------------------------------------------------- */
:root {
  /* Brand Core Palette */
  --primary: #4338ca;
  --primary-light: #6366f1;
  --primary-dark: #312e81;
  --primary-gradient: linear-gradient(135deg, #4f46e5 0%, #7c3aed 50%, #db2777 100%);
  --secondary-gradient: linear-gradient(135deg, #0ea5e9 0%, #3b82f6 50%, #6366f1 100%);
  --hero-gradient: linear-gradient(135deg, #1e1b4b 0%, #312e81 60%, #4338ca 100%);

  /* Department Color Codings (Vibrant & Accessible) */
  --color-cs: #4f46e5;
  --color-cs-bg: #eef2ff;
  --color-cs-border: #c7d2fe;

  --color-ds: #7c3aed;
  --color-ds-bg: #f5f3ff;
  --color-ds-border: #ddd6fe;

  --color-math: #0284c7;
  --color-math-bg: #f0f9ff;
  --color-math-border: #bae6fd;

  --color-bio: #059669;
  --color-bio-bg: #ecfdf5;
  --color-bio-border: #a7f3d0;

  --color-cogs: #d97706;
  --color-cogs-bg: #fffbeb;
  --color-cogs-border: #fde68a;

  --color-psyc: #0d9488;
  --color-psyc-bg: #f0fdfa;
  --color-psyc-border: #99f6e4;

  --color-econ: #ea580c;
  --color-econ-bg: #fff7ed;
  --color-econ-border: #fed7aa;

  --color-phys: #2563eb;
  --color-phys-bg: #eff6ff;
  --color-phys-border: #bfdbfe;

  --color-arts: #db2777;
  --color-arts-bg: #fdf2f8;
  --color-arts-border: #fbcfe8;

  /* Semantic UI Colors */
  --success: #059669;
  --success-bg: #d1fae5;
  --success-text: #065f46;

  --warning: #d97706;
  --warning-bg: #fef3c7;
  --warning-text: #92400e;

  --danger: #dc2626;
  --danger-bg: #fee2e2;
  --danger-text: #991b1b;

  --info: #0284c7;
  --info-bg: #e0f2fe;

